import Link from 'next/link';
import { ArrowLeft } from 'lucide-react';
import { requireModule } from '@/lib/clinic/module-guard';
import { AccessRestricted } from '@/components/feedback/access-restricted';
import { listPatientOptions } from '@/lib/clinic/patients';
import { listProfessionals } from '@/lib/clinic/professionals';
import { listAppointmentsForPatient } from '@/lib/clinic/agenda';
import { PageHeader } from '@/components/ui/page-header';
import { Card, CardBody } from '@/components/ui/card';
import { ButtonLink } from '@/components/ui/button';
import { ProntuarioForm } from '@/components/clinic/prontuario-form';

export const metadata = { title: 'Novo prontuário' };

export default async function NewProntuarioPage({
  searchParams,
}: {
  searchParams: Promise<{ paciente?: string; consulta?: string }>;
}) {
  const access = await requireModule('prontuarios');
  if (!access.allowed || !access.permissions.has('prontuarios:create')) {
    return <AccessRestricted homeHref="/app/prontuarios" homeLabel="Voltar" />;
  }

  const sp = await searchParams;
  const user = access.user;

  const [patients, professionals] = await Promise.all([
    listPatientOptions(user.id, user.activeClinicId),
    listProfessionals(user.id, user.activeClinicId),
  ]);

  // Consultas do paciente para vínculo (opcional).
  let appointments: Array<{ id: string; name: string }> = [];
  if (sp.paciente) {
    const appts = await listAppointmentsForPatient(user.id, user.activeClinicId, sp.paciente);
    appointments = appts.map((a) => ({
      id: a.id,
      name: `${a.scheduled_start.slice(0, 16).replace('T', ' ')} · ${a.type}`,
    }));
  }

  return (
    <div className="animate-fade">
      <PageHeader
        eyebrow="Clínico"
        title="Novo prontuário"
        description="Cria um rascunho. A assinatura finaliza o documento."
        actions={
          <ButtonLink href="/app/prontuarios" variant="outline" size="sm">
            <ArrowLeft className="h-3.5 w-3.5" />
            Voltar
          </ButtonLink>
        }
      />
      <Card>
        <CardBody>
          <ProntuarioForm
            mode="create"
            patients={patients}
            professionals={professionals.map((p) => ({ id: p.id, name: p.full_name }))}
            appointments={appointments}
          />
        </CardBody>
      </Card>
    </div>
  );
}
